  "talent": {
   "name": "繁育净土",
   "desc": "•「卡拉布」在队伍中时，将替换「血肉」界域为「繁育·血肉」界域。<br>• 胚胎融合：每回合获得的胚胎融合提高为 '''50~100'''，随损失生命提高，但胚胎融合上限由 '''100''' 提高为 '''200'''，达到上限时将「繁育·胚胎」置入手中。<br>• 繁育胚胎：打出时不再获得暴击率，吞噬也不再获得护盾和临时力量。每名唤醒体每回合首次消耗「繁育·胚胎」时，获得 '''40''' 层「繁育狂热」：每拥有 '''1''' 层该唤醒体本回合下次狂气爆发造成的伤害、力量和触腕伤害提高、固定中毒、固定反击、固定护盾、固定生命回复、力量降低的最终效果提高 '''1'''%。<br>• 猩红熔炉：回合开始的自动积攒量变更为 '''10'''% 已损失生命，至多积攒量变更为 '''50'''% 最大生命。战斗结束时不再积攒，使用时有 '''3''' 回合冷却。<br>• 猩红侵蚀：使用猩红熔炉后对所有敌人造成目标最大生命 '''1'''% 的侵蚀，消耗的猩红熔炉越多侵蚀效果就越强，至多提高 '''100'''%。对「空壳」敌人造成 '''5''' 倍侵蚀效果。<br>• 探索开始后，最大生命提高 '''10'''%，队伍伤害强效 +'''50'''%，每回合开始时所有唤醒体获得 '''20''' 层「繁育狂热」。如果队伍仅由血肉或混沌唤醒体组成，该效果获得的伤害强效翻倍。<br>• 界域精通变为「繁育·血肉精通」，每点界域精通使「繁育·血肉」获得的「繁育狂热」提高 '''0.05'''%。<br>• 如果队伍仅由血肉或混沌唤醒体组成，「繁育·血肉精通」效果翻倍。"
  },
