   "cost": 2,
   "desc": "“哥哥，你说靠翅膀一直飞、一直飞，到底能飞到多高？能飞到云层上面，去摸摸月亮和星星吗？”<br>“也许……可以吧？那我们要有一双很大、很有力气的翅膀才行。”<br>手抄本上深邃梦幻的银河与星座倒映进两个孩子沉沉的梦乡，化作一颗愿望的种子，埋藏入他们的心间。",
