    "name": "幻梦诗篇",
    "cost": 0,
    "desc": "她以新的姓名重生于世间，遮掩容貌，不复轮廓。<br>流传于世间的，只有以她的口吻述说的诗篇。<br>如此便已足够。<br>诗人不必拥有形貌……他们本应隐形于浓墨之中，书页之后。",
