   "cost": 1,
   "desc": "一步一步，她缓缓迈入海水中。<br>刚触及皮肤还显得稍许寒凉的入夜之海，此刻竟如人类的拥抱一般温暖。<br>海接纳了我，这样的思绪，悄然融入了宁菲亚脑中。<br>恍然间，见到了父母的笑容。在那海的深处，一定有着天伦的安乐吧。",
