    "name": "纯白梦境",
    "cost": 0,
    "desc": "柔和的海风中她陷入沉睡，却被振翅的声音惊醒。一只通体雪白的小鸟掠过她的头顶，消失在同样雪白的云朵之中。<br>那一定是梦吧，在这远离陆地的大洋深处，怎么会有落单的飞鸟呢？<br>她这么想着，却无法自已地感到一种希冀，一种向往。",
