    "弥利亚姆获得 <font color=#ddc987>35</font> 点狂气。{{词条|灵知觉醒}}：触腕上限和触腕数量 +1，对所有敌人施加 1 层{{词条|虚弱}}和{{词条|易伤}}。弥利亚姆的「打击」和「无上生祭」暴击率提高 100%。下回合开始时将 1 张「信仰的歧路」置入手中。{{词条|保留}}。{{词条|预备3}}。",
    "弥利亚姆获得 <font color=#ddc987>40</font> 点狂气.{{词条|灵知觉醒}}：触腕上限和触腕数量 +1，对所有敌人施加 1 层{{词条|虚弱}}和{{词条|易伤}}。弥利亚姆的「打击」和「无上生祭」暴击率提高 100%。下回合开始时将 1 张「信仰的歧路」置入手中。{{词条|保留}}。{{词条|预备3}}。",
    "弥利亚姆获得 <font color=#ddc987>45</font> 点狂气。{{词条|灵知觉醒}}：触腕上限和触腕数量 +1，对所有敌人施加 1 层{{词条|虚弱}}和{{词条|易伤}}。弥利亚姆的「打击」和「无上生祭」暴击率提高 100%。下回合开始时将 1 张「信仰的歧路」置入手中。{{词条|保留}}。{{词条|预备3}}。",
    "弥利亚姆获得 <font color=#ddc987>50</font> 点狂气。{{词条|灵知觉醒}}：触腕上限和触腕数量 +1，对所有敌人施加 1 层{{词条|虚弱}}和{{词条|易伤}}。弥利亚姆的「打击」和「无上生祭」暴击率提高 100%。下回合开始时将 1 张「信仰的歧路」置入手中。{{词条|保留}}。{{词条|预备3}}。\n|"
