    "name": "外域手术",
    "cost": 2,
    "desc": "有人固执地认为，身体与灵魂应是永恒的一体；也有人害怕失去肉体后，彷徨不定的神智将走向毁灭。<br>回应质疑在朵尔眼里是件麻烦事，她选择用一具又一具傀儡身体的更迭来证明手术的成功。",
