    "name": "圣血的本能",
    "cost": 2,
    "desc": "来自万古，发乎愚昧，源于恐惧。<br>奔涌在泰旖丝血管中的，是一种原始的本能。<br>在难以回首的献祭中，彼时尚为年幼的泰旖丝被植入了这种本能。<br>意志、情绪、乃至人格都被不属于她的存在取代——<br>她留下的，唯有这生命间共通的，恐惧死亡的本能。",
