    "泰旖丝获得 <font color=#ddc987>40</font> 点狂气。{{词条|灵知觉醒}}：立刻获得 1 张{{词条|圣洁之子}}。每当释放钥令时，将手中一个{{词条|胚胎}}转化为{{词条|圣洁之子}}。{{词条|保留}}。",
    "泰旖丝获得 <font color=#ddc987>45</font> 点狂气。{{词条|灵知觉醒}}：立刻获得 1 张{{词条|圣洁之子}}。每当释放钥令时，将手中一个{{词条|胚胎}}转化为{{词条|圣洁之子}}。{{词条|保留}}。",
