    "莉兹获得 <font color=#ddc987>45</font> 点狂气。{{词条|灵知觉醒}}：莉兹每造成 3 次伤害，便将 1 张具有{{词条|消耗}}的「绿炎」置入手牌，每回合最多触发 3 次。{{词条|保留}}。",
