   "desc": "宣告：<br>无法感知艺术至美的庸俗之人啊，因舞者痛哭而雀跃的狂热之人啊，对功名利禄贪得无厌的可悲之人啊。<br>此即你们的末路。<br>为你们献上这支告死之舞，让绿炎净化你们的灵魂，让优美的火焰涤荡你们污浊蒙蔽的心。<br>让我们于永恒的净土再会。",
