   "cost": 2,
   "desc": "活泼地挥动骇人巨炮，蹦蹦跳跳地进入战场。<br>不在乎烦恼，不在乎危险，因为这些与朋友相比，是那么微不足道。<br>「朋友，麻烦！莫丝，登场！」",
