    "莫丝获得 45% {{词条|基础狂气}}。{{词条|灵知觉醒}}：抽 1 张「装填！」。莫丝释放追击后下次莫丝狂气爆发额外享受 140% {{词条|触腕伤害}}加成，最多叠加 5 次。{{词条|保留}}。",
