  "talent": {
   "name": "永黯之地",
   "desc": "• 「莫丝」在队伍中时，将替换「深海」界域为「晦暝·深海」界域。<br>• 基础触腕伤害变更为队伍最大生命的 '''5'''%。<br>• 探索开始后队伍伤害强效 +'''50'''%，如果队伍仅由深海或混沌唤醒体组成，该效果获得的伤害强效翻倍，但战斗开始时不再获得额外触腕。<br>• 不再拥有「触腕集结」效果。<br>• 触腕姿态变更为「晦暝·触腕姿态」。<br>• 「晦暝·静海」：获得 '''25'''% 最大生命的护盾，回合结束后触腕不再攻击，'''3''' 回合冷却。<br>• 「神国·怒涛」：使本回合触腕伤害变成 '''125'''%，造成主动伤害后使 '''1''' 条触腕攻击，但回合结束后失去 '''1''' 条触腕，'''3''' 回合冷却。<br>• 界域精通变更为「晦暝·深海精通」，每点界域精通使「晦暝·静海」的护盾提高 '''0.025'''% 最大生命，使「晦暝·怒涛」的触腕伤害额外提高 '''0.025'''%。<br>• 如果队伍仅由深海或混沌唤醒体组成，「晦暝·界域精通」效果翻倍。"
  },
