  "talent": {
   "name": "原初吐息",
   "desc": "•「蚀灭·萝坦」在队伍中时，将替换「混沌」界域为「原初·混沌」界域。<br>• 原初灌注：基础银钥能量提高为 '''2000''' 点，队伍伤害强效 +'''50'''%，所有唤醒体的攻击和防御提高 '''10'''%。如果队伍仅由混沌唤醒体组成，该效果获得的伤害强效翻倍。战斗开始时，获得 '''2000''' 银钥能量。<br>• 万钥同源：所有唤醒体的银钥充能等级变为队伍平均值。且不再根据算力消耗获得银钥能量，而是每名唤醒体每回合首张指令卡获得「获得该唤醒体银钥充能 x '''3''' + '''100'''」的银钥能量。<br>• 未分之境：不再触发其他界域的至纯界域、精通效果翻倍、强效翻倍效果。<br>• 原初回响：{{词条|灵知觉醒}}获得{{词条|预备1}}，每回合首次打出时自动释放携带钥令。<br>• 记忆碎片：钥令被替换为「原初·双生复演」和「原初·三相天启」，本身携带的钥令无法释放。<br>&nbsp;&nbsp;&nbsp;&nbsp;○ 原初·双生复演：从持有钥令中{{词条|发现}} '''3''' 种钥令，选择 '''1''' 个钥令使其生效 '''2''' 次。<br>&nbsp;&nbsp;&nbsp;&nbsp;○ 原初·三相天启：从持有钥令中{{词条|发现}} '''3''' 组钥令，每组由 '''3''' 种不同钥令组成，选择一组使其中钥令依次生效 '''1''' 次。<br>&nbsp;&nbsp;&nbsp;&nbsp;○「原初·双生复演」和「原初·三相天启」中的钥令会包含八种「原初记忆」。<br>&nbsp;&nbsp;&nbsp;&nbsp;○「原初·双生复演」和「原初·三相天启」仅视为释放 '''1''' 次钥令，在多次生效时仅对首个生效的钥令有效。<br>&nbsp;&nbsp;&nbsp;&nbsp;○ 界域精通变为「原初·混沌精通」，每点界域精通使钥令强度提高 '''0.05'''%。<br>&nbsp;&nbsp;&nbsp;&nbsp;○ 每点钥令提高钥令造成的固定{{词条|中毒}}、固定{{词条|反击}}、固定{{词条|力量}}、固定{{词条|触腕伤害}}、固定{{词条|旧日余烬}} '''2'''%、提高固定护盾、固定生命回复、{{词条|力量降低}}、暴击率、暴击伤害、伤害强效、界域精通、狂气、{{词条|胚胎融合}}、银钥能量 '''1'''%。<br>• 如果队伍仅由混沌唤醒体组成，「原初·混沌精通」效果翻倍。"
  },
