    "cost": 1,
    "desc": "自她诞生的第一天起，她便看到命运的丝线蔓延。<br>沿着丝线的轨迹，她踏入门扉，领受她无尽的、属于囚徒的命运。<br>丝线穿过名为摩伊赖的纺轮，穿过城墙与海峡，穿过誓言与谎言，穿过每一个以为自己正在做出选择的灵魂。<br>在这自由的幻境里，纺轮转动，亘古不息。",
