  "talent": {
   "name": "命定之丝",
   "desc": "•「阿拉克涅」在队伍中时，将替换「超维」界域为「奇点·超维」界域。<br>• 维度穿梭：每回合首次打出指令卡后触发该效果，将其临时原始复制置入超维空间并为其和临时复制赋予 '''25''' 层「奇点信标」，超维回合无法发动该效果。<br>• 奇点信标：每拥有 '''1''' 层使该卡牌造成的伤害、力量和触腕伤害提高、固定中毒、固定反击最终效果提高 '''2'''%；护盾、生命回复、力量降低的最终效果提高 '''1'''%，打出后移除。拥有奇点信标的卡牌无法触发「维度穿梭」。<br>• 超维空间：当其达到上限时回合结束改为发动超维空间，不再获得额外回合，弃掉非保留手牌并触发虚无效果、将超维空间所有卡牌置入手中，将当前算力设置为 '''5''' 点。发动超维空间后，本回合视为超维回合。<br>• 奇点湮灭：取出超维空间最左侧的卡牌。'''3''' 回合冷却。<br>• 探索开始后队伍伤害强效 +'''50'''%，并获得 '''15''' 层「奇点棱镜」。<br>• 奇点棱镜：所有指令卡视为拥有等量奇点信标的加成。<br>• 超维精通：队伍每拥有 '''1''' 点界域精通，使「奇点棱镜」和「维度穿梭」施加的「奇点信标」层数提高 '''0.05'''%。<br>• 至纯超维：如果队伍仅有超维或混沌唤醒体组成，超维精通效果和界域提供的伤害强效翻倍。"
  },
