    "【{{词条|吞噬}}：获得 <font color=#b75a64>[攻击力*16%]</font> 点{{词条|力量}}和 <font color=#5eeffb>[防御力*3.2%]</font> 点{{词条|戒备}}。】获得 <font color=#5eeffb>[防御力*64%]</font> 点护盾。对所有敌人施加 <font color=#b75a64>[攻击力*120%]</font> 层{{词条|中毒}}。",
